import fs from 'node:fs';
import openapiTS, { astToString } from 'openapi-typescript';
const path = new URL('../../src/lib/api/schema.d.ts', import.meta.url);
const expected =
  '/**\n * This file was auto-generated by openapi-typescript.\n * Do not make direct changes to the file.\n */\n\n' +
  astToString(await openapiTS(new URL('../../openapi/pact-broker.yaml', import.meta.url)));
if (fs.readFileSync(path, 'utf8') !== expected) {
  console.error('Generated API types are stale. Run npm run api:generate.');
  process.exit(1);
}
console.log('Generated API types match the specification.');
